using Microsoft.AspNetCore.Components;
using sv_468037314d9242b8b3c64b2f1ddec759.Models;

namespace sv_468037314d9242b8b3c64b2f1ddec759.Components.Pages;

public partial class Settings : ComponentBase
{
    private string activeSection = "Profile";
    private bool isLoading = true;
    private string toastMessage = string.Empty;
    private string toastType = string.Empty;

    // Profile
    private EditableProfile editProfile = new();
    private UserProfile? savedProfile;

    // Notifications
    private EditableNotifications editNotifications = new();
    private List<string> availableChannels = new() { "general", "announcements", "engineering", "design", "marketing", "support" };

    // Security
    private SecuritySettings? securitySettings;
    private bool showPasswordPanel;
    private string currentPassword = string.Empty;
    private string newPassword = string.Empty;
    private string confirmPassword = string.Empty;
    private bool showRevokeConfirmation;
    private ActiveSession? sessionToRevoke;

    // Appearance
    private EditableAppearance editAppearance = new();

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        isLoading = false;
    }

    private async Task LoadAllSettings()
    {
        var profile = await SettingsService.GetProfileAsync();
        savedProfile = profile;
        editProfile = new EditableProfile
        {
            DisplayName = profile.DisplayName,
            Email = profile.Email,
            AvatarUrl = profile.AvatarUrl,
            Bio = profile.Bio
        };

        var notifications = await SettingsService.GetNotificationPrefsAsync();
        editNotifications = new EditableNotifications
        {
            EmailNotifications = notifications.EmailNotifications,
            PushNotifications = notifications.PushNotifications,
            WeeklyDigest = notifications.WeeklyDigest,
            MutedChannels = new List<string>(notifications.MutedChannels)
        };

        securitySettings = await SettingsService.GetSecuritySettingsAsync();

        var appearance = await SettingsService.GetAppearanceAsync();
        editAppearance = new EditableAppearance
        {
            Theme = appearance.Theme,
            FontSize = appearance.FontSize,
            Language = appearance.Language,
            CompactMode = appearance.CompactMode
        };
    }

    private void SetActiveSection(string section)
    {
        activeSection = section;
        DismissToast();
    }

    // === Profile ===

    private async Task SaveProfile()
    {
        var profile = new UserProfile(editProfile.DisplayName, editProfile.Email, editProfile.AvatarUrl, editProfile.Bio);
        await SettingsService.SaveProfileAsync(profile);
        savedProfile = profile;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        if (savedProfile is not null)
        {
