+    align-items: center;
+    gap: 0.75rem;
+    cursor: pointer;
+    font-weight: 500;
+}
+
+.toggle-label input[type="checkbox"] {
+    position: relative;
+    width: 44px;
+    height: 24px;
+    appearance: none;
+    background-color: #d1d5db;
+    border-radius: 12px;
+    cursor: pointer;
+    transition: background-color 0.2s;
+}
+
+.toggle-label input[type="checkbox"]:checked {
+    background-color: #4f46e5;
+}
+
+.toggle-label input[type="checkbox"]::before {
+    content: '';
+    position: absolute;
+    top: 2px;
+    left: 2px;
+    width: 20px;
+    height: 20px;
+    background: white;
+    border-radius: 50%;
+    transition: transform 0.2s;
+}
+
+.toggle-label input[type="checkbox"]:checked::before {
+    transform: translateX(20px);
+}
+
+/* Status Indicator */
+.status-indicator {
+    font-size: 0.85rem;
+    font-weight: 500;
+    padding: 0.25rem 0.625rem;
+    border-radius: 1rem;
+}
+
+.status-enabled {
+    background-color: #d1fae5;
+    color: #065f46;
+}
+
+.status-disabled {
+    background-color: #fee2e2;
+    color: #991b1b;
+}
+
+/* Channel List */
+.channel-list {
