+    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
+    gap: 0.5rem;
+}
+
+.channel-item {
+    display: flex;
+    align-items: center;
+    gap: 0.5rem;
+    padding: 0.5rem 0.75rem;
+    background: #f9fafb;
+    border-radius: 0.375rem;
+    cursor: pointer;
+}
+
+.channel-item:hover {
+    background: #f3f4f6;
+}
+
+/* Expandable Panel */
+.expandable-panel {
+    margin-bottom: 1.5rem;
+    border: 1px solid #e5e7eb;
+    border-radius: 0.5rem;
+    overflow: hidden;
+}
+
+.panel-header {
+    width: 100%;
+    padding: 0.875rem 1rem;
+    background: #f9fafb;
+    border: none;
+    cursor: pointer;
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    font-size: 1rem;
+    font-weight: 500;
+}
+
+.panel-header:hover {
+    background: #f3f4f6;
+}
+
+.panel-body {
+    padding: 1.25rem;
+    border-top: 1px solid #e5e7eb;
+}
+
+.expand-icon {
+    font-size: 0.75rem;
+}
+
+/* Sessions Table */
+.sessions-table {
+    width: 100%;
+    border-collapse: collapse;
+    margin-top: 0.5rem;
+}
+
+.sessions-table th,
+.sessions-table td {
+    padding: 0.75rem;
+    text-align: left;
+    border-bottom: 1px solid #e5e7eb;
+}
+
+.sessions-table th {
+    background: #f9fafb;
+    font-weight: 600;
+    font-size: 0.85rem;
+    text-transform: uppercase;
+    letter-spacing: 0.025em;
+}
+
+.current-badge {
+    font-size: 0.8rem;
+    padding: 0.2rem 0.5rem;
+    background: #dbeafe;
+    color: #1e40af;
+    border-radius: 0.25rem;
+    font-weight: 500;
+}
+
+/* Radio Groups */
+.radio-group {
+    display: flex;
+    gap: 1.5rem;
+    margin-top: 0.25rem;
+}
+
+.radio-label {
+    display: flex;
+    align-items: center;
+    gap: 0.375rem;
+    cursor: pointer;
+}
+
+/* Modal */
+.modal-overlay {
+    position: fixed;
+    inset: 0;
+    background: rgba(0, 0, 0, 0.5);
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 1000;
+}
+
+.modal-dialog {
+    background: white;
+    padding: 2rem;
+    border-radius: 0.75rem;
+    max-width: 420px;
+    width: 90%;
+    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
+}
+
+.modal-dialog h3 {
+    margin-top: 0;
+}
+
+/* Live Preview */
+.live-preview {
+    border: 1px solid #e5e7eb;
+    border-radius: 0.5rem;
+    padding: 1.25rem;
+    margin-bottom: 1rem;
+    transition: all 0.3s;
+}
+
+.preview-header {
+    font-weight: 600;
+    margin-bottom: 0.5rem;
+    padding-bottom: 0.5rem;
+    border-bottom: 1px solid #e5e7eb;
+}
+
+.preview-body {
+    margin: 0.5rem 0;
+}
+
+.preview-sidebar {
+    margin-top: 0.75rem;
+    padding: 0.5rem;
+    background: #f3f4f6;
+    border-radius: 0.25rem;
+    font-size: 0.9rem;
+}
+
+/* Preview Theme Variants */
+.preview-theme-light {
+    background: #ffffff;
+    color: #1f2937;
+}
+
+.preview-theme-dark {
+    background: #1f2937;
+    color: #f9fafb;
+}
+
+.preview-theme-dark .preview-sidebar {
+    background: #374151;
+}
+
+.preview-theme-dark .preview-header {
+    border-color: #4b5563;
+}
+
+.preview-theme-system {
+    background: #f9fafb;
+    color: #374151;
+}
+
+/* Preview Font Sizes */
+.preview-font-small {
+    font-size: 0.8rem;
+}
+
+.preview-font-medium {
+    font-size: 1rem;
+}
+
+.preview-font-large {
+    font-size: 1.2rem;
+}
+
+/* Preview Compact */
+.preview-compact {
+    padding: 0.625rem;
+    line-height: 1.3;
+}
+
+.preview-compact .preview-header {
+    margin-bottom: 0.25rem;
+    padding-bottom: 0.25rem;
+}
+
+.preview-compact .preview-body {
+    margin: 0.25rem 0;
+}
+
+.preview-compact .preview-sidebar {
+    margin-top: 0.375rem;
+    padding: 0.25rem 0.5rem;
+}
+
+/* Loading */
+.loading-spinner {
+    text-align: center;
+    padding: 3rem;
+    font-size: 1.1rem;
+    color: #6b7280;
+}
+
+.info-text {
+    font-size: 0.9rem;
+    color: #6b7280;
+    margin: 0.5rem 0;
+}
